class Interpolation:
    def __init__(self):
        pass

    @staticmethod
    def _interpolate_1d_segment(x, y, xi):
        """Calculate 1D interpolation value for a single query point xi."""
        for i in range(len(x) - 1):
            if x[i] <= xi <= x[i + 1]:
                return y[i] + (y[i + 1] - y[i]) * (xi - x[i]) / (x[i + 1] - x[i])
        return None

    @staticmethod
    def _interpolate_2d_segment(x, y, z, xi, yi):
        """Calculate 2D bilinear interpolation value for a single query point (xi, yi)."""
        for i in range(len(x) - 1):
            if x[i] <= xi <= x[i + 1]:
                for j in range(len(y) - 1):
                    if y[j] <= yi <= y[j + 1]:
                        dx1 = x[i + 1] - xi
                        dx0 = xi - x[i]
                        dy1 = y[j + 1] - yi
                        dy0 = yi - y[j]
                        denominator = (x[i + 1] - x[i]) * (y[j + 1] - y[j])
                        return (z[i][j] * dx1 * dy1 +
                                z[i + 1][j] * dx0 * dy1 +
                                z[i][j + 1] * dx1 * dy0 +
                                z[i + 1][j + 1] * dx0 * dy0) / denominator
        return None

    @staticmethod
    def interpolate_1d(x, y, x_interp):
        """Perform 1D linear interpolation."""
        return [Interpolation._interpolate_1d_segment(x, y, xi) for xi in x_interp]

    @staticmethod
    def interpolate_2d(x, y, z, x_interp, y_interp):
        """Perform 2D bilinear interpolation."""
        return [
            Interpolation._interpolate_2d_segment(x, y, z, xi, yi)
            for xi, yi in zip(x_interp, y_interp)
        ]
